void GameStack::push(GameState gs) {
    if (stack.size() >= maxSize) {
        stack.erase(stack.begin()); // Remove oldest
    }
    stack.push_back(gs);
}

GameState GameStack::pop() {
    if (stack.empty()) throw std::runtime_error("Stack is empty");
    GameState gs = stack.back();
    stack.pop_back();
    return gs;
}

